/**
 * Returns the oldest key for a user if OATHPrioritizedModules is not set
 *
 * @param User $user The user to check
 * @return string|null The oldest key or null if none found
 */
public function getOldestKeyForUser(User $user): ?string {
    // Check if OATHPrioritizedModules is set
    if ($user->getOption('OATHPrioritizedModules')) {
        return null;
    }

    // Fetch all keys associated with the user
    $keys = $this->getKeyStore()->getKeysByUser($user);

    // If no keys are found, return null
    if (empty($keys)) {
        return null;
    }

    // Sort the keys by creation time (oldest first)
    usort($keys, function (Key $a, Key $b) {
        return $a->getCreationTime() <=> $b->getCreationTime();
    });

    // Return the oldest key
    return $keys[0]->getKeyId();
}
