const { rest } = require('some-rest-library');
const { RequestContext } = require('@mediawiki/context');

class CodeMirrorLintService {
	constructor(restClient) {
		this.restClient = restClient;
		this.currentRequest = null;
	}

	async lint(doc) {
		if (this.currentRequest) {
			this.currentRequest.abort();
		}

		try {
			this.currentRequest = this.restClient.post('/v1/transform/wikitext/to/lint', {
				wikitext: doc.toString(),
				timeout: 30000 // Default timeout of 30 seconds
			});

			const errors = await this.currentRequest;
			return errors;
		} catch (error) {
			mw.log.warn('[CodeMirror] Error during linting:', error);
			throw error;
		} finally {
			this.currentRequest = null;
		}
	}
}

module.exports = CodeMirrorLintService;
```

This revision addresses the review comments by adding a timeout and aborting previous requests before making a new one. It also includes error handling and logging warnings using `mw.log.warn`. The `timeout` option is set to the default 30 seconds provided by `mw.Rest`.

