const errors = await new Promise((resolve, reject) => {
    let controller = new AbortController();
    let signal = controller.signal;

    // Abort previous request if any
    if (this.previousRequest) {
        this.previousRequest.abort();
    }

    this.previousRequest = fetch('/v1/transform/wikitext/to/lint', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ wikitext: doc.toString() }),
        signal: signal
    })
    .then(response => response.json())
    .then(data => {
        this.previousRequest = null;
        resolve(data);
    })
    .catch(error => {
        this.previousRequest = null;
        if (error.name === 'AbortError') {
            mw.log.warn('[CodeMirror] Request aborted');
        } else {
            mw.log.error('[CodeMirror] Error:', error);
            reject(error);
        }
    });

    // Set timeout for the request
    setTimeout(() => {
        controller.abort();
        mw.log.warn('[CodeMirror] Request timed out');
    }, 3000); // 3 seconds timeout
});
